using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/events/{eventId:int}/categories")]
public class CategoriesController(RaceDayDbContext db):ControllerBase {
 int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [HttpGet,AllowAnonymous] public async Task<IActionResult> Get(int eventId)=>!await db.Events.AnyAsync(e=>e.EventId==eventId)?NotFound():Ok(await db.Categories.Where(c=>c.EventId==eventId).ToListAsync());
 [Authorize(Roles=Roles.Organiser),HttpPost] public async Task<IActionResult> Create(int eventId,CategoryRequest r){var e=await db.Events.FindAsync(eventId);if(e==null)return NotFound();if(e.OrganiserId!=UserId)return Forbid();var c=new Category{EventId=eventId,Name=r.Name.Trim(),CategoryType=r.CategoryType,MinimumAge=r.MinimumAge,MaximumAge=r.MaximumAge,DistanceKm=r.DistanceKm};db.Categories.Add(c);await db.SaveChangesAsync();return Created($"/api/events/{eventId}/categories/{c.CategoryId}",c);}
 [Authorize(Roles=Roles.Organiser),HttpPut("{categoryId:int}")] public async Task<IActionResult> Update(int eventId,int categoryId,CategoryRequest r){var c=await db.Categories.Include(x=>x.Event).FirstOrDefaultAsync(x=>x.EventId==eventId&&x.CategoryId==categoryId);if(c==null)return NotFound();if(c.Event!.OrganiserId!=UserId)return Forbid();c.Name=r.Name.Trim();c.CategoryType=r.CategoryType;c.MinimumAge=r.MinimumAge;c.MaximumAge=r.MaximumAge;c.DistanceKm=r.DistanceKm;await db.SaveChangesAsync();return Ok(c);}
 [Authorize(Roles=Roles.Organiser),HttpDelete("{categoryId:int}")] public async Task<IActionResult> Delete(int eventId,int categoryId){var c=await db.Categories.Include(x=>x.Event).Include(x=>x.Enrolments).FirstOrDefaultAsync(x=>x.EventId==eventId&&x.CategoryId==categoryId);if(c==null)return NotFound();if(c.Event!.OrganiserId!=UserId)return Forbid();if(c.Enrolments.Count>0)return Conflict(new{message="Cannot delete a category with enrolments."});db.Categories.Remove(c);await db.SaveChangesAsync();return NoContent();}
}
